package com.bank.flink.sp;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;

// The job's state: per-account fraud score, tagged with the operator uid
// that owns it (savepoint restore matches state to operators by uid).
class JobState {
    private final String operatorUid;
    private final Map<String, BigDecimal> fraudScores = new HashMap<>();

    JobState(String operatorUid) {
        this.operatorUid = operatorUid;
    }

    String getOperatorUid() { return operatorUid; }
    Map<String, BigDecimal> getFraudScores() { return fraudScores; }

    void score(String accountId, BigDecimal delta) {
        fraudScores.merge(accountId, delta, BigDecimal::add);
    }

    JobState copy() {
        JobState c = new JobState(operatorUid);
        c.fraudScores.putAll(this.fraudScores);
        return c;
    }
}
