package com.bank.flink.sp;

import java.util.logging.Logger;

// Automatic fault-tolerance snapshots. Keeps ONLY the latest; older ones
// are superseded. Owned by Flink, used transparently for crash recovery.
class CheckpointManager {
    private static final Logger log = Logger.getLogger(CheckpointManager.class.getName());

    private JobState latest;          // only the newest checkpoint is kept
    private long checkpointId = 0;

    void autoCheckpoint(JobState live) {
        checkpointId++;
        JobState old = latest;
        latest = live.copy();
        log.info(() -> "AUTO checkpoint " + checkpointId + " taken"
                + (old != null ? " (superseded previous)" : "")
                + " scores=" + latest.getFraudScores());
    }

    // Restore transparently after a crash from the latest checkpoint.
    JobState restoreAfterCrash() {
        log.info(() -> "RESTORE from latest checkpoint " + checkpointId
                + " scores=" + latest.getFraudScores());
        return latest.copy();
    }
}
