package com.bank.flink.sp;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.logging.Logger;

// User-triggered, retained, portable snapshots for upgrades/rescaling.
// Keeps ALL savepoints until explicitly removed. Restore matches by uid.
class SavepointManager {
    private static final Logger log = Logger.getLogger(SavepointManager.class.getName());

    // path -> snapshot (all retained)
    private final Map<String, JobState> savepoints = new LinkedHashMap<>();

    String takeSavepoint(String path, JobState live) {
        savepoints.put(path, live.copy());
        log.info(() -> "SAVEPOINT taken at " + path + " uid=" + live.getOperatorUid()
                + " scores=" + live.getFraudScores());
        return path;
    }

    // Restore into a NEW job version/parallelism, matching state by operator uid.
    JobState restoreInto(String path, String newOperatorUid, int newParallelism) {
        JobState sp = savepoints.get(path);
        if (sp == null) throw new IllegalArgumentException("No savepoint at " + path);
        if (!sp.getOperatorUid().equals(newOperatorUid)) {
            log.severe(() -> "uid MISMATCH: savepoint uid=" + sp.getOperatorUid()
                    + " new op uid=" + newOperatorUid + " -> state would be orphaned");
            throw new IllegalStateException("operator uid mismatch");
        }
        JobState restored = new JobState(newOperatorUid);
        restored.getFraudScores().putAll(sp.getFraudScores());
        log.info(() -> "RESTORE savepoint " + path + " into new job (parallelism="
                + newParallelism + ") scores=" + restored.getFraudScores());
        return restored;
    }
}
