package com.bank.flink.sp;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: automatic checkpoints + crash recovery, then a user
// savepoint used to upgrade and rescale the job.
public class CheckpointVsSavepointDemo {
    private static final Logger log = Logger.getLogger(CheckpointVsSavepointDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new SpLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        String uid = "fraud-scoring-op";
        JobState live = new JobState(uid);
        CheckpointManager checkpoints = new CheckpointManager();
        SavepointManager savepoints = new SavepointManager();

        // Process some transactions and take automatic checkpoints.
        live.score("SAV2001", new BigDecimal("10"));
        checkpoints.autoCheckpoint(live);
        live.score("CUR3001", new BigDecimal("5"));
        checkpoints.autoCheckpoint(live);          // supersedes the first

        // CRASH: Flink recovers automatically from the latest checkpoint.
        live = checkpoints.restoreAfterCrash();
        log.info(() -> "After auto-recovery, resume processing...");
        live.score("SAV2001", new BigDecimal("20"));

        // Planned UPGRADE: take a savepoint, stop, start new version rescaled.
        String spPath = savepoints.takeSavepoint("s3://nbi-flink/savepoints/sp-upgrade-1", live);

        // New job version: same operator uid (so state matches), parallelism 2 -> 6.
        JobState upgraded = savepoints.restoreInto(spPath, uid, 6);
        upgraded.score("SAV2001", new BigDecimal("1")); // new model continues from carried state
        log.info(() -> "Upgraded job SAV2001 score = " + upgraded.getFraudScores().get("SAV2001"));
    }
}

